-- Happy Scribe — Транскрипція
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'happyscribe.com' OR LOWER(`name`) = LOWER('Happy Scribe'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Happy Scribe', NULL, 'https://www.happyscribe.com', NULL, NULL, 'AI-транскрипція та субтитри понад 150 мовами, нотатки й підсумки зустрічей, а за потреби — вичитка тексту людиною.', 'AI transcription and subtitles in 150+ languages, meeting notes and summaries, plus optional human proofreading.', 'Happy Scribe перетворює аудіо й відео на текст і субтитри понад 150 мовами. Транскрипт можна вичитати в редакторі та експортувати в потрібному форматі. Сервіс також записує зустрічі та робить нотатки, підсумки й список дій, а в платних тарифах доступний AI-чат з транскриптами. Якщо потрібна максимальна точність, текст може вичитати людина (від $2 за хвилину). Тарифи (при річній оплаті): Free — пробні 10 хвилин; Basic — $8,50 на місяць (120 хв); Pro — $19 на місяць (600 хв); Business — $59 на місяць (6 000 хв); помісячно — $17, $29 і $89. Додаткові хвилини — $0,20.', 'Happy Scribe turns audio and video into text and subtitles in more than 150 languages. You can proofread a transcript in the editor and export it in the format you need. It also records meetings and produces notes, summaries and action items, and paid plans add AI chat with your transcripts. When maximum accuracy matters, a human can proofread the text (from $2 a minute). Plans (billed annually): Free — a 10-minute trial; Basic — $8.50 a month (120 min); Pro — $19 a month (600 min); Business — $59 a month (6,000 min); billed monthly — $17, $29 and $89. Extra minutes cost $0.20.', 'Транскрипція й субтитри 150+ мовами
Редактор і експорт у різних форматах
Нотатки, підсумки й дії зі зустрічей
Вичитка людиною за потреби', 'Transcription and subtitles in 150+ languages
Editor and export in multiple formats
Meeting notes, summaries and action items
Optional human proofreading', 'Журналісти, відеомейкери, дослідники й команди, яким потрібні точні транскрипти та субтитри.', 'Journalists, video creators, researchers and teams that need accurate transcripts and subtitles.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
