-- Notta — Транскрипція
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'notta.ai' OR LOWER(`name`) = LOWER('Notta'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Notta', NULL, 'https://www.notta.ai', NULL, NULL, 'AI-транскрипція зустрічей, аудіо й відео в реальному часі з розпізнаванням спікерів, підсумками та інтеграцією з Zoom, Google Meet і Teams.', 'Real-time AI transcription of meetings, audio and video with speaker identification, summaries and integration with Zoom, Google Meet and Teams.', 'Notta перетворює зустрічі, аудіо та відео на текст, у якому зручно шукати. Він транскрибує в реальному часі, розпізнає спікерів, підтримує власний словник термінів і двомовну транскрипцію, а після зустрічі готує AI-підсумок, документи й надсилає результати в Slack. Записувати зустрічі в Zoom, Google Meet і Microsoft Teams можна як за допомогою бота, так і без нього. Сервіс відповідає SOC 2, ISO 27001, GDPR і HIPAA. Тарифи: Free — 120 хв на місяць (до 3 хв на запис); Pro — $13,99 на місяць (1 800 хв, записи до 5 годин); Business — $27,99 на місяць (необмежена транскрипція, командна робота); при річній оплаті на 40% дешевше; Enterprise — за запитом.', 'Notta turns meetings, audio and video into searchable text. It transcribes in real time, identifies speakers, supports a custom vocabulary and bilingual transcription, and after a meeting produces an AI summary and documents and sends results to Slack. Meetings in Zoom, Google Meet and Microsoft Teams can be recorded with or without a bot. It is SOC 2, ISO 27001, GDPR and HIPAA compliant. Plans: Free — 120 min a month (up to 3 min per recording); Pro — $13.99 a month (1,800 min, recordings up to 5 hours); Business — $27.99 a month (unlimited transcription, team collaboration); 40% cheaper billed annually; Enterprise on request.', 'Транскрипція в реальному часі
Розпізнавання спікерів і власний словник
Запис Zoom, Google Meet, Teams з ботом або без
AI-підсумки та інтеграція зі Slack', 'Real-time transcription
Speaker identification and custom vocabulary
Records Zoom, Google Meet and Teams with or without a bot
AI summaries and Slack integration', 'Команди, менеджери й фахівці з продажів, які проводять багато онлайн-зустрічей.', 'Teams, managers and sales professionals who run a lot of online meetings.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
