SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'turboscribe.ai' OR LOWER(`name`) = LOWER('TurboScribe'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TurboScribe', NULL, 'https://turboscribe.ai', NULL, NULL, 'Швидка AI-транскрипція аудіо й відео з необмеженою кількістю файлів у платному тарифі, файлами до 10 годин і перекладом понад 130 мовами.', 'Fast AI transcription of audio and video with unlimited files on the paid plan, files up to 10 hours and translation into 130+ languages.', 'TurboScribe розшифровує аудіо- та відеофайли в текст і орієнтований на великі обсяги за фіксовану ціну. Безкоштовно можна транскрибувати 3 файли на день тривалістю до 30 хвилин. Тариф Unlimited знімає обмеження на кількість транскрипцій для одного користувача: файли до 10 годин або 5 ГБ, до 50 файлів одночасно, усі режими транскрипції, переклад понад 134 мовами, масовий експорт і необмежене сховище. Unlimited коштує $120 на рік ($10 на місяць) при річній оплаті; помісячна оплата вдвічі дорожча.', 'TurboScribe converts audio and video files to text and is aimed at large volumes for a flat price. For free you can transcribe 3 files a day of up to 30 minutes each. The Unlimited plan removes the limit on transcriptions for one user: files up to 10 hours or 5 GB, up to 50 files at once, all transcription modes, translation into 134+ languages, bulk export and unlimited storage. Unlimited costs $120 a year ($10 a month) billed annually; monthly billing costs twice as much.', 'Необмежені транскрипції в тарифі Unlimited
Файли до 10 годин, до 50 одночасно
Переклад понад 134 мовами
Масовий експорт і необмежене сховище', 'Unlimited transcriptions on the Unlimited plan
Files up to 10 hours, up to 50 at once
Translation into 134+ languages
Bulk export and unlimited storage', 'Подкастери, журналісти, студенти й дослідники, яким треба розшифровувати багато записів.', 'Podcasters, journalists, students and researchers who need to transcribe lots of recordings.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
