SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'macwhisper.com' OR LOWER(`name`) = LOWER('MacWhisper'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'MacWhisper', NULL, 'https://www.macwhisper.com', NULL, NULL, 'Транскрипція на самому Mac за допомогою моделей Whisper: файли, записи зустрічей і системна диктовка без відправлення аудіо в хмару; є версія для iPhone та iPad.', 'On-device transcription on your Mac with Whisper models: files, meeting recordings and system-wide dictation without sending audio to the cloud; also available for iPhone and iPad.', 'MacWhisper — застосунок для macOS, який транскрибує аудіо локально за допомогою моделей Whisper, тож записи не залишають ваш комп''ютер. Досить перетягнути файл, щоб отримати якісний текст; можна записувати з мікрофона, автоматично записувати зустрічі в Zoom, Teams, Webex, Discord та інших програмах, шукати за текстом і спікерами в усіх транскриптах і редагувати їх у зручному редакторі. Системна диктовка на базі Whisper може замінити стандартну диктовку Apple. У версії Pro доступні всі моделі, покращення тексту й робота з AI-сервісами (OpenAI, Anthropic, Groq, Ollama та інші) через власні ключі, переклад через DeepL. Базова версія безкоштовна; ліцензія Pro для особистого використання — €65 одноразово, є пакети для команд. Застосунок доступний і для iPhone та iPad.', 'MacWhisper is a macOS app that transcribes audio locally with Whisper models, so recordings never leave your computer. Just drag in a file to get a high-quality transcript; you can also record from a microphone, automatically record meetings in Zoom, Teams, Webex, Discord and other apps, search by text and speaker across all transcripts and edit them in a capable editor. Whisper-based system-wide dictation can replace Apple''s built-in dictation. Pro unlocks all models, text clean-up and AI services (OpenAI, Anthropic, Groq, Ollama and more) with your own keys, plus translation via DeepL. The basic version is free; a Pro licence for personal use is a one-time €65, with team packs available. The app is also available for iPhone and iPad.', 'Локальна транскрипція моделями Whisper
Автозапис зустрічей у Zoom, Teams, Webex
Системна диктовка на базі Whisper
Пошук за текстом і спікерами
Версія для iPhone та iPad', 'Local transcription with Whisper models
Automatic meeting recording in Zoom, Teams, Webex
Whisper-based system-wide dictation
Search by text and speaker
Also on iPhone and iPad', 'Користувачі Mac, для яких важлива приватність: журналісти, юристи, дослідники, автори.', 'Mac users who care about privacy: journalists, lawyers, researchers and writers.', 'desktop,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
