SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'tactiq.io' OR LOWER(`name`) = LOWER('Tactiq'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Tactiq', NULL, 'https://tactiq.io', NULL, NULL, 'Розширення Chrome для транскрипції онлайн-зустрічей у реальному часі з AI-підсумками й діями; не потребує бота в дзвінку.', 'A Chrome extension for real-time transcription of online meetings with AI summaries and action items; no bot needs to join the call.', 'Tactiq транскрибує онлайн-зустрічі прямо в браузері: розширення для Chrome фіксує розмову в реальному часі без додавання бота до дзвінка. Після зустрічі AI готує підсумки, ключові висновки та список дій, транскрипти можна ділити з колегами й експортувати, а під час зустрічі доступні AI-підказки. У командних тарифах транскрипти автоматично надсилаються учасникам команди. Тарифи (при річній оплаті, за користувача на місяць): Free — 10 транскриптів і 5 AI-кредитів на місяць; Pro — $8 (необмежені транскрипти, 10 AI-кредитів); Team — $16,67 (необмежені AI-кредити, до 20 користувачів); Business — $29,17 (20–200 користувачів).', 'Tactiq transcribes online meetings right in the browser: the Chrome extension captures the conversation in real time without adding a bot to the call. After the meeting AI prepares summaries, key takeaways and action items, transcripts can be shared with colleagues and exported, and in-meeting AI is available during the call. Team plans automatically share transcripts with the team. Plans (billed annually, per user a month): Free — 10 transcripts and 5 AI credits a month; Pro — $8 (unlimited transcripts, 10 AI credits); Team — $16.67 (unlimited AI credits, up to 20 users); Business — $29.17 (20–200 users).', 'Транскрипція зустрічей у реальному часі без бота
AI-підсумки, висновки й дії
AI-підказки під час зустрічі
Спільний доступ і експорт транскриптів', 'Real-time meeting transcription without a bot
AI summaries, takeaways and action items
In-meeting AI
Transcript sharing and export', 'Працівники й команди, які щодня проводять онлайн-зустрічі та хочуть мати текст і підсумки.', 'Professionals and teams who have online meetings every day and want transcripts and summaries.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
